SELECT AVG(Age) AS Average_Age, MIN(Age) AS Min_Age, MAX(Age) AS Max_Age
FROM singer
WHERE Country = 'France';

SELECT AVG(Age) AS Average_Age, MIN(Age) AS Min_Age, MAX(Age) AS Max_Age
FROM singer
WHERE Country = 'France';

SELECT Country, COUNT(*) AS Number_of_Singers
FROM singer
GROUP BY Country;

SELECT Country, COUNT(*) AS Singer_Count
FROM singer
GROUP BY Country;

SELECT s.Name, s.Country
FROM singer s
WHERE s.Song_Name LIKE '%Hey%';

SELECT COUNT(concert_ID) 
FROM concert 
WHERE Stadium_ID = (SELECT Stadium_ID FROM stadium ORDER BY Capacity DESC LIMIT 1);

SELECT COUNT(concert_ID) 
FROM concert 
WHERE Stadium_ID = (SELECT Stadium_ID FROM stadium ORDER BY Capacity DESC LIMIT 1);

SELECT PetType, AVG(pet_age) AS AverageAge, MAX(pet_age) AS MaxAge
FROM Pets
GROUP BY PetType;

SELECT PetType, AVG(weight) AS AverageWeight
FROM Pets
GROUP BY PetType;

SELECT PetType, AVG(weight) AS AverageWeight
FROM Pets
GROUP BY PetType;

SELECT s.Fname, s.Age
FROM Student s
JOIN Has_Pet hp ON s.StuID = hp.StuID;

SELECT DISTINCT s.Fname, s.Age
FROM Student s
JOIN Has_Pet hp ON s.StuID = hp.StuID;

SELECT StuID, COUNT(PetID) AS PetCount
FROM Has_Pet
GROUP BY StuID;

SELECT AVG(Student.Age) 
FROM Student 
WHERE StuID NOT IN (SELECT StuID FROM Has_Pet);

SELECT AVG(Student.Age) 
FROM Student 
WHERE StuID NOT IN (SELECT StuID FROM Has_Pet);

SELECT car_makers.Maker, model_list.Model
FROM car_makers
JOIN model_list ON car_makers.Id = model_list.Maker;

SELECT car_makers.Maker, model_list.Model
FROM car_makers
JOIN model_list ON car_makers.Id = model_list.Maker;

SELECT c.CountryName, c.CountryId
FROM countries c
WHERE c.CountryId IN (
    SELECT m.Country
    FROM car_makers m
);

SELECT Year, AVG(Weight) AS AverageWeight
FROM cars_data
GROUP BY Year;

SELECT AVG(Weight) AS AverageWeight, Year
FROM cars_data
GROUP BY Year;

SELECT AVG(Horsepower) AS AverageHorsepower
FROM cars_data
WHERE Year < 1980;

SELECT Cylinders, MAX(Accelerate) AS MaxAccelerate
FROM cars_data
GROUP BY Cylinders;

SELECT MAX(Accelerate) AS MaxAccelerate, Cylinders
FROM cars_data
GROUP BY Cylinders;

SELECT FullName, Id FROM car_makers WHERE Id IN (
    SELECT Maker FROM model_list GROUP BY Maker HAVING COUNT(*) > 3
)

SELECT Id, Maker FROM car_makers WHERE Id IN (
    SELECT Maker FROM model_list GROUP BY Maker HAVING COUNT(*) >= 2
) AND Id IN (
    SELECT Maker FROM car_makers GROUP BY Maker HAVING COUNT(*) > 3
);

SELECT CountryId, CountryName FROM countries
WHERE CountryId IN (
    SELECT Country FROM car_makers GROUP BY Country HAVING COUNT(*) > 3
) OR CountryId IN (
    SELECT Country FROM car_makers WHERE Id IN (
        SELECT Maker FROM model_list WHERE Model IN (
            SELECT Model FROM car_names
        )
    )
);
